        let mut child = Command::new("piton")
            .arg("lsp")
            .current_dir(project_dir)
            .stdin(Stdio::piped())
            .stdout(Stdio::piped())
            .stderr(Stdio::piped())
            .spawn()
            .context("could not start `piton lsp`")?;
        let stdin: Stdin = Arc::new(Mutex::new(
            child
                .stdin
                .take()
                .ok_or_else(|| anyhow!("`piton lsp` has no stdin"))?,
        ));
