            .stdout
            .take()
            .ok_or_else(|| anyhow!("`piton lsp` has no stdout"))?;
        let stderr_pipe = child
            .stderr
            .take()
            .ok_or_else(|| anyhow!("`piton lsp` has no stderr"))?;
